        com.codahale.metrics.Timer.Context context = timer.time()) {
        MixedOperation<SparkApplication, SparkApplicationResourceList, Resource<SparkApplication>> sparkApplicationClient = client.resources(SparkApplication.class, SparkApplicationResourceList.class);
        SparkApplicationResourceList list = sparkApplicationClient.inNamespace(sparkCluster.getSparkApplicationNamespace()).list();
